import { statSync } from "node:fs";
import { join } from "node:path";
import { NAME_PATTERNS, type SpringKind } from "@pso/core";
import { CliError } from "./fsx.ts";
import { camel, pascal } from "./templates.ts";
import { nodeTemplate, springTemplate, type Generated, type MakeOpts } from "./generators.ts";

/**
 * Generators of the official structures:
 *   orchestrator (modular)   application-wide kinds in src/.app/<kind>/ (module kinds are generated by the module-aware commands)
 *   Spring (layered)         every kind in its package: application/{rest,service,dto/request,dto/response,mapper,event},
 *                            infrastructure/{persistence,entity,config,security,filter,client}, shared/exception
 */

/** the .app directory of each application-wide orchestrator kind */
export const APP_KIND: Readonly<Record<string, "middlewares" | "filters" | "guards" | "configs" | "contracts" | "interceptors" | "decorators">> = {
  middleware: "middlewares", filter: "filters", guard: "guards", config: "configs", contract: "contracts", interceptor: "interceptors", decorator: "decorators",
};
const NODE_SUFFIX: Readonly<Record<string, string>> = { middleware: ".middleware.ts", filter: ".filter.ts", guard: ".guard.ts", config: ".config.ts", contract: ".contract.json", interceptor: ".interceptor.ts", decorator: ".decorator.ts" };

export function modularNodeFiles(kind: string, rawName: string, opts: MakeOpts): Generated {
  if (!NAME_PATTERNS.kebab.test(rawName)) throw new CliError(`Invalid name "${rawName}"`, "Use kebab-case, e.g. request-timing");
  const dir = APP_KIND[kind];
  // services, providers and hooks belong to a module in the modular structure
  if (!dir) throw new CliError(`In the modular structure a ${kind} belongs to a module`, kind === "service" ? "pso make:service <module> <name>" : `pso make:${kind} <name> --module <module>`);
  const file = `src/.app/${dir}/${rawName}${NODE_SUFFIX[kind]}`;
  const route = opts.route ?? `/${rawName}`, method = (opts.method ?? "GET").toUpperCase();
  if (kind === "interceptor") return { files: { [file]: interceptorSource(rawName) } };
  if (kind === "decorator") return { files: { [file]: decoratorSource(rawName) } };
  if (kind === "config") return { files: { [file]: nodeTemplate("config", rawName, route, method).split(`"../../configs/${rawName}.config"`).join(`"<relative path>/.app/configs/${rawName}.config"`).split("src/configs/").join("src/.app/configs/") } };
  return { files: { [file]: nodeTemplate(kind, rawName, route, method) } };
}

function interceptorSource(id: string): string {
  return [
    `import { log, type Interceptor } from "@pso/http";`,
    ``,
    `/**`,
    ` * Interceptor "${id}": runs around the action of every route that names it (\`interceptors: ["${id}"]\` in a ROUTES.pso.ts), after the`,
    ` * guards and the middleware. \`next()\` runs the action (and the interceptors after this one) and resolves with its result; what this`,
    ` * function returns is what the route answers. An error thrown here is handled like an error of the action (Problem Details).`,
    ` */`,
    `const interceptor: Interceptor = async (call, next) => {`,
    `  const started = performance.now();`,
    `  try {`,
    `    return await next();`,
    `  } finally {`,
    `    log("info", "action timed", { component: "${id}", route: \`\${call.route.method} \${call.route.path}\`, ms: Math.round(performance.now() - started) });`,
    `  }`,
    `};`,
    `export default interceptor;`,
    ``,
  ].join("\n");
}

function decoratorSource(id: string): string {
  const fn = pascal(id), getter = `${camel(id)}Of`;
  return [
    `import "reflect-metadata";`,
    ``,
    `/**`,
    ` * Decorator "${id}": reusable application metadata on a method. It only records the metadata; code that wants to act on it reads`,
    ` * it with ${getter}(target, method). Routing, security and validation are never declared with custom decorators: they belong to`,
    ` * ROUTES.pso.ts and the @pso/http decorators.`,
    ` */`,
    `const KEY = "app:${id}";`,
    ``,
    `export const ${fn} = (value: string | true = true): MethodDecorator => (target, method) => {`,
    `  Reflect.defineMetadata(KEY, value, target, method);`,
    `};`,
    ``,
    `export const ${getter} = (target: object, method: string | symbol): string | true | undefined => Reflect.getMetadata(KEY, target, method) as string | true | undefined;`,
    ``,
  ].join("\n");
}

const SPRING_SUFFIX: Readonly<Partial<Record<SpringKind, string>>> = {
  controller: "Controller", service: "Service", mapper: "Mapper", repository: "Repository", event: "Event", listener: "Listener", config: "Config", guard: "Guard",
  entity: "Entity", filter: "Filter", exception: "Exception", client: "Client", request: "Request", response: "Response",
};
const SPRING_LAYERED_PKG: Readonly<Partial<Record<SpringKind, string>>> = {
  controller: "application/rest", service: "application/service", request: "application/dto/request", response: "application/dto/response",
  mapper: "application/mapper", repository: "infrastructure/persistence", entity: "infrastructure/entity", config: "infrastructure/config",
  guard: "infrastructure/security", filter: "infrastructure/filter", client: "infrastructure/client", exception: "shared/exception",
  event: "application/event", listener: "application/event",
};

const lines = (...l: string[]): string => l.join("\n") + "\n";

export function layeredSpringFiles(kind: string, rawName: string, basePkg: string, opts: MakeOpts): Generated {
  const kebab = rawName.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();
  if (!NAME_PATTERNS.kebab.test(kebab)) throw new CliError(`Invalid name "${rawName}"`, "Use kebab-case, e.g. customer-orders");
  if (kind === "port" || kind === "adapter") throw new CliError(`The layered structure has no ${kind}s`, "Services coordinate repositories directly (application/service); outbound calls are clients (pso make:client). Add hexagonal ports when the service really needs them");
  const effective = (kind === "dto" ? (opts.response ? "response" : "request") : kind) as SpringKind;
  const pkgRel = SPRING_LAYERED_PKG[effective];
  if (!pkgRel) throw new CliError(`Kind "${kind}" has no place in the layered structure`);
  const pkg = `${basePkg}.${pkgRel.split("/").join(".")}`;
  const cls = pascal(kebab);
  const route = opts.route ?? `/${kebab}`, method = (opts.method ?? "GET").toUpperCase();
  const file = `src/main/java/${pkg.split(".").join("/")}/${cls}${SPRING_SUFFIX[effective]}.java`;
  const head = `package ${pkg};`;
  const table = `${kebab.replace(/-/g, "_")}s`;
  let body: string;
  switch (effective) {
    case "controller": case "service": case "mapper": case "event": case "listener": case "config": case "guard":
      body = springTemplate(effective, pkg, cls, route, method, opts.servicePrefix ?? "");
      break;
    case "request":
      body = lines(head, "", "import jakarta.validation.constraints.NotBlank;", "import jakarta.validation.constraints.Size;", "",
        "/** A request body: an immutable record validated with Jakarta Validation (@Valid in the controller). */",
        `public record ${cls}Request(@NotBlank @Size(max = 120) String name) {`, "}");
      break;
    case "response":
      body = lines(head, "", "import java.util.UUID;", "", "/** A response body: what the API returns (never a JPA entity). */", `public record ${cls}Response(UUID id, String name) {`, "}");
      break;
    case "entity":
      body = lines(head, "",
        "import jakarta.persistence.Column;", "import jakarta.persistence.Entity;", "import jakarta.persistence.GeneratedValue;", "import jakarta.persistence.GenerationType;",
        "import jakarta.persistence.Id;", "import jakarta.persistence.Table;", "import jakarta.persistence.Version;", "import java.time.Instant;", "import java.util.UUID;",
        "import lombok.AccessLevel;", "import lombok.Getter;", "import lombok.NoArgsConstructor;", "import org.hibernate.annotations.CreationTimestamp;", "import org.hibernate.annotations.UpdateTimestamp;", "",
        "/**", ` * JPA entity of the ${table} table. Flyway owns the schema: create the table with pso make:migration create-${table.replace(/_/g, "-")} --service <service>`,
        " * (Hibernate validates this mapping against it and refuses to start when they differ). Never return the entity from a controller.", " */",
        "@Entity", `@Table(name = "${table}")`, "@Getter", "@NoArgsConstructor(access = AccessLevel.PROTECTED)", `public class ${cls}Entity {`, "",
        "    @Id", "    @GeneratedValue(strategy = GenerationType.UUID)", "    private UUID id;", "",
        "    @CreationTimestamp", "    @Column(name = \"created_at\", nullable = false, updatable = false)", "    private Instant createdAt;", "",
        "    @UpdateTimestamp", "    @Column(name = \"updated_at\", nullable = false)", "    private Instant updatedAt;", "",
        "    @Version", "    @Column(name = \"version\", nullable = false)", "    private long version;", "}");
      break;
    case "repository": {
      const entity = `src/main/java/${basePkg.split(".").join("/")}/infrastructure/entity/${cls}Entity.java`;
      if (opts.projectRoot && !statSync(join(opts.projectRoot, ...entity.split("/")), { throwIfNoEntry: false })) throw new CliError(`${cls}Repository needs the entity ${cls}Entity`, `Run pso make:entity ${kebab} first (or pso make:crud ${kebab} for the whole resource)`);
      body = lines(head, "", `import ${basePkg}.infrastructure.entity.${cls}Entity;`, "import java.util.UUID;", "import org.springframework.data.jpa.repository.JpaRepository;", "",
        `/** Spring Data repository of ${cls}Entity: the persistence the services in application/service use. */`, `public interface ${cls}Repository extends JpaRepository<${cls}Entity, UUID> {`, "}");
      break;
    }
    case "filter":
      body = lines(head, "", "import jakarta.servlet.FilterChain;", "import jakarta.servlet.ServletException;", "import jakarta.servlet.http.HttpServletRequest;", "import jakarta.servlet.http.HttpServletResponse;",
        "import java.io.IOException;", "import org.springframework.stereotype.Component;", "import org.springframework.web.filter.OncePerRequestFilter;", "",
        "/**", " * Servlet filter, applied to every request. Keep it technical (correlation, headers, metrics): authorization belongs to @PreAuthorize", " * or pso.security.rules, never to a filter.", " */",
        "@Component", `public class ${cls}Filter extends OncePerRequestFilter {`, "", "    @Override",
        "    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain) throws ServletException, IOException {",
        "        chain.doFilter(request, response);", "    }", "}");
      break;
    case "exception": {
      const code = kebab.replace(/-/g, "_");
      body = lines(head, "", "import com.pso.spring.autoconfigure.problem.PsoProblemException;", "import org.springframework.http.HttpStatus;", "",
        "/**", ` * An application error answered as an RFC 9457 problem with the code "${code}". Choose the status that describes it (409 for a`,
        " * conflict with the current state, 422 for a rule the request breaks, 400 for invalid input); the detail is a sentence you write,", " * never an exception message or caller input.", " */",
        `public class ${cls}Exception extends PsoProblemException {`, "", `    public ${cls}Exception(String detail) {`, `        super(HttpStatus.CONFLICT, "${code}", detail);`, "    }", "}");
      break;
    }
    case "client":
      body = lines(head, "", "import com.pso.spring.http.PsoHttpClient;", "import lombok.RequiredArgsConstructor;", "import org.springframework.stereotype.Component;", "",
        "/**", ` * Calls the service "${kebab}" through PsoHttpClient: only services declared under pso.http.client.services can be reached (declare`,
        ` * ${kebab} there with its base URL and TLS settings), redirects are never followed, responses are size-limited, and the caller's token`, " * travels only when forward-bearer is true for that service.", " */",
        "@Component", "@RequiredArgsConstructor", `public class ${cls}Client {`, "", `    private static final String SERVICE = "${kebab}";`, "", "    private final PsoHttpClient http;", "",
        "    public <T> T get(String path, Class<T> type, Object... uriVariables) {", "        return http.get(SERVICE, path, type, uriVariables);", "    }", "}");
      break;
    default:
      throw new CliError(`Kind "${kind}" has no template in the layered structure`);
  }
  return { files: { [file]: body } };
}
